"""Presentation of the monthly P&L table for the finance team."""

from __future__ import annotations

import pandas as pd


def _format_amount(value: float) -> str:
    """Accounting style: 1,234.50, (634.20) for negatives, - for zero, empty for missing."""
    if pd.isna(value):
        return ""
    amount = round(float(value), 2)
    if amount == 0:
        return "-"
    text = f"{abs(amount):,.2f}"
    return f"({text})" if amount < 0 else text


def format_for_display(table: pd.DataFrame) -> pd.DataFrame:
    """Return a copy of the account x month table with every cell formatted as a display string."""
    return table.map(_format_amount).astype(object)

